enum FuUswidHeaderFlag {
    None = 0b0,
    Compressed = 0b1,
}

#[derive(ToString, FromString)]
enum FuUswidPayloadCompression {
    None = 0x00,
    Zlib = 0x01,
    Lzma = 0x02,
}

#[derive(New, ValidateStream, ParseStream)]
struct FuStructUswid {
    magic: Guid == 0x53424F4DD6BA2EACA3E67A52AAEE3BAF,
    hdrver: u8,
    hdrsz: u16le = $struct_size,
    payloadsz: u32le,
    flags: u8,
    compression: u8,
}
meson.build:258:libjcat = dependency('jcat', version: '>= 0.2.0', fallback: ['libjcat', 'libjcat_dep'])
meson.build:603:# take foo.rs and generate foo-struct.c and foo-struct.h files like protobuf_c
subprojects/libjcat.wrap:2:directory = libjcat
subprojects/libjcat.wrap:3:url = https://github.com/hughsie/libjcat.git
subprojects/.gitignore:4:libjcat
